class MaskedLogMixin:
    @staticmethod
    def mask_email(value):
        local, _, domain = value.partition('@')
        return local[:1] + '***@' + domain

    def log_row(self, row):
        logger.info(
            'exporting customer id=%s email=%s',
            row['id'],
            self.mask_email(row['email']),
        )


class CustomerExportService(MaskedLogMixin):
    def iter_rows(self, rows):
        buffer = io.StringIO()
        writer = csv.writer(buffer)
        for row in rows:
            self.log_row(row)
            writer.writerow([row['id'], row['email']])
            yield buffer.getvalue()
            buffer.seek(0)
            buffer.truncate(0)

    def stream(self, rows):
        return StreamingResponse(self.iter_rows(rows), media_type='text/csv')

