class CredentialStrippingMixin:
    hidden_fields = ('password_hash', 'api_secret', 'private_key')

    def strip(self, payload):
        return {k: v for k, v in payload.items() if k not in self.hidden_fields}


class UserPresenter(CredentialStrippingMixin):
    def present(self, row):
        raw = {
            'id': row.id,
            'username': row.username,
            'password_hash': row.password_hash,
            'api_secret': row.api_secret,
            'has_password': bool(row.password_hash),
        }
        return self.strip(raw)


