class RetentionGuardMixin:
    retention_days = 730
    model = None

    def purge(self, session, now):
        cutoff = now - timedelta(days=self.retention_days)
        result = session.execute(delete(self.model).where(self.model.created_at < cutoff))
        session.commit()
        return result.rowcount


class ClosedCustomerPurge(RetentionGuardMixin):
    model = Customer

    def run(self, session, now):
        removed = self.purge(session, now)
        return {'deleted': removed, 'retention_days': self.retention_days}


